import sys
from collections import defaultdict

def main():
    import sys
    import math
    from collections import Counter

    def readints():
        return list(map(int, sys.stdin.read().split()))

    data = readints()
    N = data[0]
    K = data[1]
    A = data[2:]

    if N == 2:
        print(A[0], A[1])
        return

    def get_differences(arr):
        diffs = []
        for i in range(1, len(arr)):
            diffs.append(arr[i] - arr[i - 1])
        return diffs

    def count_changes_for_d(d, A):
        if d == 0:
            return N - A.count(A[0])
        dp = defaultdict(int)
        for i in range(1, N):
            expected = A[0] + i * d
            dp[A[i]] += 1
            dp[expected] -= 1
        return N - max(dp.values())

    def find_best_progression(A, K):
        A.sort()
        min_a0 = float('inf')
        min_d = float('inf')
        best_A = None

        for i in range(N - 1):
            for j in range(i + 1, N):
                d = (A[j] - A[i]) / (j - i)
                if d.is_integer():
                    d = int(d)
                    changes_needed = count_changes_for_d(d, A)
                    if changes_needed <= K:
                        a0 = A[i] - i * d
                        if (a0, d) < (min_a0, min_d):
                            min_a0, min_d = a0, d
                            best_A = [a0 + k * d for k in range(N)]

        return best_A

    result = find_best_progression(A, K)
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
